// Shared metric road operations. Demo generation/dispatch only; imported engine geometry is unchanged.
import {hash,roadClass} from './lowpoly.js';
export const streetWidth=r=>Number.isFinite(r.pavementWidthM)?r.pavementWidthM:['primary','secondary'].includes(roadClass(r))?17:roadClass(r)==='tertiary'?12:8.5;
export const lengthOf=ps=>ps.slice(1).reduce((s,p,i)=>s+Math.hypot(p.x-ps[i].x,p.z-ps[i].z),0);
export function samplePath(ps,d){let travelled=0;for(let i=1;i<ps.length;i++){const a=ps[i-1],b=ps[i],len=Math.hypot(b.x-a.x,b.z-a.z);if(d<=travelled+len||i===ps.length-1){const t=Math.max(0,Math.min(1,(d-travelled)/(len||1)));return {x:a.x+(b.x-a.x)*t,z:a.z+(b.z-a.z)*t,dx:(b.x-a.x)/(len||1),dz:(b.z-a.z)/(len||1),distance:d};}travelled+=len;}return {...ps[0],dx:1,dz:0,distance:0};}
export function projectPoint(p,ps){let best=null,travelled=0;for(let i=1;i<ps.length;i++){const a=ps[i-1],b=ps[i],dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz);if(!len)continue;const t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.z-a.z)*dz)/(len*len))),x=a.x+dx*t,z=a.z+dz*t,dist=Math.hypot(p.x-x,p.z-z);if(!best||dist<best.offset)best={x,z,dx:dx/len,dz:dz/len,distance:travelled+len*t,offset:dist};travelled+=len;}return best;}
export function pathBetween(ps,start,end){const total=lengthOf(ps),a=Math.max(0,Math.min(total,start)),b=Math.max(0,Math.min(total,end));if(a>b)return pathBetween(ps,b,a).reverse();const out=[samplePath(ps,a)];let d=0;for(let i=1;i<ps.length;i++){d+=Math.hypot(ps[i].x-ps[i-1].x,ps[i].z-ps[i-1].z);if(d>a&&d<b)out.push(ps[i]);}out.push(samplePath(ps,b));return out.map(({x,z})=>({x,z}));}
export class RoadIndex{
 constructor(roads){this.roads=roads;this.grid=new Map();this.size=64;for(const road of roads)for(let i=1;i<road.points.length;i++){const a=road.points[i-1],b=road.points[i],seg={a,b,road};for(let x=Math.floor((Math.min(a.x,b.x)-14)/64);x<=Math.floor((Math.max(a.x,b.x)+14)/64);x++)for(let z=Math.floor((Math.min(a.z,b.z)-14)/64);z<=Math.floor((Math.max(a.z,b.z)+14)/64);z++){const key=x+':'+z;if(!this.grid.has(key))this.grid.set(key,[]);this.grid.get(key).push(seg);}}}
 nearby(p){return this.grid.get(Math.floor(p.x/64)+':'+Math.floor(p.z/64))||[];}
 onCarriageway(p,margin=.25){return this.nearby(p).some(s=>projectPoint(p,[s.a,s.b]).offset<streetWidth(s.road)/2+margin);}
 nearest(p){let best=null;const roads=[...new Set(this.nearby(p).map(s=>s.road))];for(const r of roads.length?roads:this.roads){const q=projectPoint(p,r.points);if(q&&(!best||q.offset<best.offset))best={...q,road:r};}return best;}
}
export function roadside(q,road,side=1){const offset=streetWidth(road)/2+1.05;return {x:q.x-q.dz*offset*side,z:q.z+q.dx*offset*side,angle:Math.atan2(-q.dz*side,q.dx*side)};}
export function prepareDemoNetwork(town,heightAt){
 const homes=new Map(town.premises.map(h=>[h.id,h])),roads=new Map(town.roads.map(r=>[r.id,r])),index=new RoadIndex(town.roads),net=town.networks.electric,nodes=new Map(net.nodes.map(n=>[n.id,n])),parents=new Map(net.edges.map(e=>[e.to,e])),nodeRoad=new Map(),roadEdges=new Map();
 for(const e of net.edges){if(e.roadId){nodeRoad.set(e.from,e.roadId);nodeRoad.set(e.to,e.roadId);if(!roadEdges.has(e.roadId))roadEdges.set(e.roadId,[]);roadEdges.get(e.roadId).push(e);}}
 const placement=r=>['residential','living_street','service','unclassified'].includes(roadClass(r))&&hash(town.seed+':buried-street:'+(r.name||r.id))%6===0?'underground':'overhead';
 for(const n of net.nodes){if(n.kind==='meter'||['external_supply','substation'].includes(n.kind))continue;let road=roads.get(nodeRoad.get(n.id));if(!road&&n.kind==='transformer')road=roads.get(nodeRoad.get(parents.get(n.id)?.from));if(!road)continue;const q=projectPoint(n,road.points),p=roadside(q,road);n.x=p.x;n.z=p.z;n.elevationM=heightAt(n.x,n.z);n.roadId=road.id;n.placement=placement(road);}
 for(const e of net.edges){const a=nodes.get(e.from),b=nodes.get(e.to),road=roads.get(e.roadId||a.roadId||b.roadId);if(road){e.roadId=road.id;e.placement=placement(road);if(e.kind==='distribution')e.points=e.points.map(p=>roadside(projectPoint(p,road.points),road));else if(e.kind==='service'){const h=homes.get(b.premiseId),qa=projectPoint(a,road.points),qb=projectPoint(h.front||h,road.points);e.points=pathBetween(road.points,qa.distance,qb.distance).map(p=>roadside(projectPoint(p,road.points),road));}else e.points=[];e.points=[{x:a.x,z:a.z},...e.points,{x:b.x,z:b.z}];}else{e.points=[{x:a.x,z:a.z},{x:b.x,z:b.z}];}e.lengthM=lengthOf(e.points);}
 const poles=[],poleGrid=new Map();const poleKey=(x,z)=>Math.floor(x/28)+':'+Math.floor(z/28);const spaced=p=>{for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++)for(const q of poleGrid.get(poleKey(p.x+dx*28,p.z+dz*28))||[])if(Math.hypot(p.x-q.x,p.z-q.z)<28)return false;const k=poleKey(p.x,p.z);if(!poleGrid.has(k))poleGrid.set(k,[]);poleGrid.get(k).push(p);return true;};
 for(const road of town.roads){if(placement(road)!=='overhead')continue;const candidates=roadEdges.get(road.id)||[];if(!candidates.length)continue;const length=lengthOf(road.points),n=Math.max(1,Math.ceil(length/42));for(let i=0;i<n;i++){const q=samplePath(road.points,(i+.5)*length/n),p=roadside(q,road);if(index.onCarriageway(p)||!spaced(p))continue;const edge=candidates.reduce((best,e)=>{const offset=Math.min(...e.points.map(a=>Math.hypot(a.x-p.x,a.z-p.z)));return !best||offset<best.offset?{edge:e,offset}:best;},null).edge;poles.push({id:'POLE-'+road.id+'-'+i,...p,roadId:road.id,edgeId:edge.id,heightM:10,lamp:i%2===0,placement:'sidewalk',elevationM:heightAt(p.x,p.z)});}}
 town.poles=poles;town.viewerLayoutVersion='roadside-demo/1.0';return town;
}

export class RoadRouter{
 constructor(roads){this.roads=roads;this.index=new RoadIndex(roads);this.adj=new Map();this.byId=new Map(roads.map(r=>[r.id,r]));this.ends=new Map();for(const road of roads){const ra=road.a||this.key(road.points[0]),rb=road.b||this.key(road.points.at(-1));this.ends.set(road.id,{a:ra,b:rb});for(const [a,b,reverse] of [[ra,rb,false],[rb,ra,true]]){if(!this.adj.has(a))this.adj.set(a,[]);this.adj.get(a).push({to:b,road,reverse,length:lengthOf(road.points)});}}}
 key(p){return p.x.toFixed(2)+':'+p.z.toFixed(2);}
 route(from,to){const a=this.index.nearest(from),b=this.index.nearest(to);if(!a||!b)throw Error('No road access.');const al=lengthOf(a.road.points),bl=lengthOf(b.road.points),dist=new Map(),prev=new Map(),visited=new Set();const seeds=[[this.ends.get(a.road.id).a,a.distance,pathBetween(a.road.points,a.distance,0)],[this.ends.get(a.road.id).b,al-a.distance,pathBetween(a.road.points,a.distance,al)]];
  for(const [id,d,points]of seeds)if(d<(dist.get(id)??Infinity)){dist.set(id,d);prev.set(id,{points,from:null});}
  // Binary heap keeps route requests cheap for the 10k-town graph.
  const heap=[];const push=v=>{let i=heap.length;heap.push(v);while(i>0){const p=(i-1)>>1;if(heap[p].d<=v.d)break;heap[i]=heap[p];i=p;}heap[i]=v;};const pop=()=>{const first=heap[0],last=heap.pop();if(heap.length){let i=0;while(i*2+1<heap.length){let c=i*2+1;if(c+1<heap.length&&heap[c+1].d<heap[c].d)c++;if(heap[c].d>=last.d)break;heap[i]=heap[c];i=c;}heap[i]=last;}return first;};for(const [id,d]of dist)push({id,d});
  while(heap.length){const {id,d}=pop();if(visited.has(id))continue;visited.add(id);for(const e of this.adj.get(id)||[]){const nd=d+e.length;if(nd<(dist.get(e.to)??Infinity)){dist.set(e.to,nd);prev.set(e.to,{from:id,points:e.reverse?[...e.road.points].reverse():e.road.points});push({id:e.to,d:nd});}}}
  let best=a.road.id===b.road.id?{length:Math.abs(a.distance-b.distance),points:pathBetween(a.road.points,a.distance,b.distance)}:null;
  for(const [id,tail,remaining]of [[this.ends.get(b.road.id).a,pathBetween(b.road.points,0,b.distance),b.distance],[this.ends.get(b.road.id).b,pathBetween(b.road.points,bl,b.distance),bl-b.distance]]){const length=(dist.get(id)??Infinity)+remaining;if(!Number.isFinite(length)||best&&length>=best.length)continue;let cursor=id,chunks=[tail];while(cursor!==null){const link=prev.get(cursor);if(!link)break;chunks.unshift(link.points);cursor=link.from;}best={length,points:chunks.flat()};}
  if(!best)throw Error('This road is disconnected from the depot.');best.points=best.points.filter((p,i,ps)=>!i||Math.hypot(p.x-ps[i-1].x,p.z-ps[i-1].z)>.001).map(({x,z})=>({x,z}));if(best.points.length<2)best.points.push({...best.points[0]});return {...best,start:a,end:b};
 }
}
